tools.example:
nb = NotebookOpen["report.nb", Visible -> False];
NotebookEvaluate[nb, InsertResults -> True];
NotebookSave[nb];
NotebookClose[nb]

expr = NotebookGet[EvaluationNotebook[]];
inputs = Cases[expr, Cell[BoxData[b_], "Input", ___] :> b, Infinity];
NotebookPut[expr /. "Text" -> "Item"]

SelectionMove[nb, Next, Cell];
cell = NotebookRead[nb]
NotebookRead[First[Cells[nb, CellStyle -> "Title"]]]

nb = EvaluationNotebook[];
SelectionMove[nb, After, Notebook];
NotebookWrite[nb, Cell["Appended text", "Text"]];
SelectionMove[nb, Previous, Cell]; SelectionEvaluate[nb]

inputs = Cells[nb, CellStyle -> "Input"];
SetOptions[#, Background -> LightYellow] & /@ inputs;
NotebookRead[inputs]

c = EvaluationCell[];
SetOptions[c, Background -> LightBlue];
SetOptions[NextCell[c, CellStyle -> "Output"], CellTags -> {"result"}]

nb = NotebookGet["file.nb"];
clean = DeleteCases[nb, (CellChangeTimes | CellLabel | CellID) -> _, Infinity];
NotebookPut[clean]

nb = Get["analysis.nb"];
nb2 = nb /. Cell[c_, "Output", o___] :> Sequence[];
Export["analysis-stripped.nb", nb2]

nb = CreateDocument[{TextCell["Report", "Title"], ExpressionCell[Plot[Sin[x], {x, 0, 6}]]}, Visible -> False];
Export["report.pdf", nb];
NotebookClose[nb]
